-- Only Admins may delete leads (owner decision, 2026-11-13).
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE. Later changes go in a new file.
--
-- Add-only: the existing delete policies (admin_delete_leads, own_lead_delete) stay as they are.
-- This adds one RESTRICTIVE policy, which Postgres combines with AND on top of them, so a delete
-- now needs both an existing permissive policy and is_admin(). Sales, Digital Marketing and
-- Secretary can still read and edit their own leads; they just cannot delete them.

create policy leads_delete_admin_only on public.leads
    as restrictive
    for delete
    to authenticated
    using ((select public.is_admin()));
